CREATE TABLE "mfg_schedules" (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,source_id TEXT NOT NULL,state TEXT NOT NULL,object_version INT NOT NULL DEFAULT 1,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,id)); CREATE INDEX ON "mfg_schedules"(tenant_id,source_id);
CREATE TABLE "mfg_commitments" (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,source_id TEXT NOT NULL,state TEXT NOT NULL,object_version INT NOT NULL DEFAULT 1,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,id)); CREATE INDEX ON "mfg_commitments"(tenant_id,source_id);
CREATE TABLE "mfg_procurements" (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,source_id TEXT NOT NULL,state TEXT NOT NULL,object_version INT NOT NULL DEFAULT 1,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,id)); CREATE INDEX ON "mfg_procurements"(tenant_id,source_id);
CREATE TABLE "mfg_restarts" (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,source_id TEXT NOT NULL,state TEXT NOT NULL,object_version INT NOT NULL DEFAULT 1,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,id)); CREATE INDEX ON "mfg_restarts"(tenant_id,source_id);
CREATE TABLE "mfg_scraps" (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,source_id TEXT NOT NULL,state TEXT NOT NULL,object_version INT NOT NULL DEFAULT 1,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,id)); CREATE INDEX ON "mfg_scraps"(tenant_id,source_id);
CREATE TABLE "mfg_engineering_changes" (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,source_id TEXT NOT NULL,state TEXT NOT NULL,object_version INT NOT NULL DEFAULT 1,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,id)); CREATE INDEX ON "mfg_engineering_changes"(tenant_id,source_id);
CREATE TABLE "mfg_demands" (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,source_id TEXT NOT NULL,state TEXT NOT NULL,object_version INT NOT NULL DEFAULT 1,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,id)); CREATE INDEX ON "mfg_demands"(tenant_id,source_id);
CREATE TABLE "mfg_qualifications" (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,source_id TEXT NOT NULL,state TEXT NOT NULL,object_version INT NOT NULL DEFAULT 1,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,id)); CREATE INDEX ON "mfg_qualifications"(tenant_id,source_id);
CREATE TABLE "mfg_source_bindings" (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,source_id TEXT NOT NULL,state TEXT NOT NULL,object_version INT NOT NULL DEFAULT 1,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,id)); CREATE INDEX ON "mfg_source_bindings"(tenant_id,source_id);
CREATE TABLE mfg_control_events(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,operation_id TEXT NOT NULL,actor TEXT NOT NULL,kind TEXT NOT NULL,source_id TEXT NOT NULL,payload JSONB NOT NULL,result JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,operation_id));
CREATE TABLE stock_quality_lots(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,item_id TEXT NOT NULL,warehouse_id TEXT NOT NULL,location_id TEXT,source_kind TEXT NOT NULL,source_ref_id TEXT NOT NULL,quality_state TEXT NOT NULL CHECK(quality_state IN ('pending','qualified','quarantine','unknown')),quantity DOUBLE PRECISION NOT NULL CHECK(quantity>=0),object_version INT NOT NULL DEFAULT 1,received_at TIMESTAMPTZ NOT NULL,evidence JSONB NOT NULL,UNIQUE(tenant_id,id)); CREATE INDEX ON stock_quality_lots(tenant_id,item_id,warehouse_id); CREATE INDEX ON stock_quality_lots(tenant_id,source_ref_id);
CREATE TABLE stock_quality_reservations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,reservation_key TEXT NOT NULL,lot_id TEXT NOT NULL,quantity DOUBLE PRECISION NOT NULL CHECK(quantity>=0),remaining DOUBLE PRECISION NOT NULL CHECK(remaining>=0 AND remaining<=quantity),object_version INT NOT NULL DEFAULT 1,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,lot_id) REFERENCES stock_quality_lots(tenant_id,id)); CREATE INDEX ON stock_quality_reservations(tenant_id,reservation_key);
CREATE TABLE stock_quality_events(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,source_key TEXT NOT NULL,kind TEXT NOT NULL,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,source_key));
INSERT INTO stock_quality_lots(id,tenant_id,item_id,warehouse_id,location_id,source_kind,source_ref_id,quality_state,quantity,received_at,evidence) SELECT 'legacy-location:'||id,tenant_id,item_id,warehouse_id,location_id,'legacy',id,'unknown',qty,created_at,jsonb_build_object('basis','pre-upgrade location balance without quality evidence') FROM stock_location_balances WHERE qty>0;
INSERT INTO stock_quality_lots(id,tenant_id,item_id,warehouse_id,location_id,source_kind,source_ref_id,quality_state,quantity,received_at,evidence) SELECT 'legacy-residual:'||a.id,a.tenant_id,a.item_id,a.warehouse_id,NULL,'legacy',a.id,'unknown',a.qty_on_hand-coalesce(b.qty,0),a.created_at,jsonb_build_object('basis','unlocated physical residual without quality evidence') FROM stock_accounts a LEFT JOIN (SELECT tenant_id,item_id,warehouse_id,sum(quantity) AS qty FROM stock_quality_lots GROUP BY 1,2,3) b USING(tenant_id,item_id,warehouse_id) WHERE a.qty_on_hand>coalesce(b.qty,0);
INSERT INTO mfg_source_bindings(id,tenant_id,source_id,state,data) SELECT 'legacy-po:'||id,tenant_id,id,'legacy-approved',jsonb_build_object('kind','legacy-po','snapshot',to_jsonb(p)) FROM purchase_orders p WHERE state IN ('approved','issued','received');
INSERT INTO mfg_source_bindings(id,tenant_id,source_id,state,data) SELECT 'legacy-scrap:'||id,tenant_id,id,'legacy-scrap',jsonb_build_object('kind','legacy-scrap','snapshot',to_jsonb(n)) FROM nonconformities n WHERE disposal='scrap' AND state IN ('disposed','closed');
INSERT INTO mfg_restarts(id,tenant_id,source_id,state,data) SELECT 'legacy-fault:'||id,tenant_id,id,'awaiting-signatures',jsonb_build_object('faultVersion',object_version,'equipmentCode',equipment_code,'signatures','[]'::jsonb,'basis','existing fault retained; no approval invented') FROM fault_reports;
ALTER TABLE mfg_schedules ENABLE ROW LEVEL SECURITY; ALTER TABLE mfg_schedules FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_isolation ON mfg_schedules FOR ALL TO PUBLIC USING(tenant_id=current_setting('app.current_tenant',true)::text) WITH CHECK(tenant_id=current_setting('app.current_tenant',true)::text); DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='app_user') THEN GRANT SELECT,INSERT,UPDATE,DELETE ON mfg_schedules TO app_user; END IF; END $$;
